// Simple application for agent to work on
// Self-contained HTTP app with no external dependencies.

const http = require('http');

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

function sendJson(res, statusCode, body) {
  const payload = JSON.stringify(body);
  res.statusCode = statusCode;
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('Content-Length', Buffer.byteLength(payload));
  res.end(payload);
}

function app(req, res) {
  const url = new URL(req.url, 'http://localhost');

  if (req.method === 'GET' && url.pathname === '/health') {
    return sendJson(res, 200, { status: 'ok', timestamp: new Date().toISOString() });
  }

  if (req.method === 'GET' && url.pathname === '/users') {
    return sendJson(res, 200, users);
  }

  return sendJson(res, 404, { error: 'Not found' });
}

app.listen = (...args) => http.createServer(app).listen(...args);

if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;

{
  "name": "simple-agent-app",
  "version": "1.0.0",
  "private": true,
  "main": "app.js",
  "scripts": {
    "test": "node test.js",
    "start": "node app.js"
  }
}

const assert = require('assert');
const app = require('./app');

function request(path) {
  return new Promise((resolve, reject) => {
    const server = app.listen(0, () => {
      const { port } = server.address();
      fetch(`http://127.0.0.1:${port}${path}`)
        .then(async (res) => {
          const body = await res.json();
          resolve({ status: res.status, body });
        })
        .catch(reject)
        .finally(() => server.close());
    });
    server.on('error', reject);
  });
}

(async () => {
  const health = await request('/health');
  assert.strictEqual(health.status, 200);
  assert.strictEqual(health.body.status, 'ok');
  assert.match(health.body.timestamp, /^\d{4}-\d{2}-\d{2}T/);

  const users = await request('/users');
  assert.strictEqual(users.status, 200);
  assert.deepStrictEqual(users.body, [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);

  const missing = await request('/missing');
  assert.strictEqual(missing.status, 404);
  assert.deepStrictEqual(missing.body, { error: 'Not found' });

  console.log('All tests passed');
})().catch((error) => {
  console.error(error);
  process.exit(1);
});

