// Simple application for agent to work on
// Uses only Node's built-in HTTP module so the project can run without
// downloading external dependencies.

const http = require('http');

function createApp() {
  const routes = [];

  const app = (req, res) => {
    res.json = (body) => {
      const payload = JSON.stringify(body);
      res.statusCode = res.statusCode || 200;
      res.setHeader('Content-Type', 'application/json; charset=utf-8');
      res.setHeader('Content-Length', Buffer.byteLength(payload));
      res.end(payload);
    };

    const requestUrl = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    const route = routes.find(
      (candidate) => candidate.method === req.method && candidate.path === requestUrl.pathname,
    );

    if (!route) {
      res.statusCode = 404;
      return res.json({ error: 'Not found' });
    }

    return route.handler(req, res);
  };

  app.get = (path, handler) => {
    routes.push({ method: 'GET', path, handler });
    return app;
  };

  app.listen = (...args) => http.createServer(app).listen(...args);

  return app;
}

const app = createApp();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;

const assert = require('assert');
const http = require('http');
const app = require('./app');

function request(server, path) {
  const { port } = server.address();

  return new Promise((resolve, reject) => {
    const req = http.get({ host: '127.0.0.1', port, path }, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: JSON.parse(body),
        });
      });
    });

    req.on('error', reject);
  });
}

(async () => {
  const server = app.listen(0);

  try {
    const health = await request(server, '/health');
    assert.strictEqual(health.statusCode, 200);
    assert.strictEqual(health.body.status, 'ok');
    assert.ok(!Number.isNaN(Date.parse(health.body.timestamp)));

    const users = await request(server, '/users');
    assert.strictEqual(users.statusCode, 200);
    assert.deepStrictEqual(users.body, [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);

    const missing = await request(server, '/missing');
    assert.strictEqual(missing.statusCode, 404);
    assert.deepStrictEqual(missing.body, { error: 'Not found' });

    console.log('All tests passed.');
  } finally {
    server.close();
  }
})().catch((error) => {
  console.error(error);
  process.exit(1);
});

