// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const http = require('http');

function createApp() {
  const routes = [];

  const app = (req, res) => {
    res.status = (code) => {
      res.statusCode = code;
      return res;
    };

    res.json = (body) => {
      res.setHeader('Content-Type', 'application/json');
      res.end(JSON.stringify(body));
    };

    const url = new URL(req.url, 'http://localhost');
    const route = routes.find(
      (candidate) => candidate.method === req.method && candidate.path === url.pathname,
    );

    if (!route) {
      return res.status(404).json({ error: 'Not found' });
    }

    return route.handler(req, res);
  };

  app.get = (path, handler) => {
    routes.push({ method: 'GET', path, handler });
    return app;
  };

  app.listen = (...args) => http.createServer(app).listen(...args);

  return app;
}

const app = createApp();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

if (require.main === module) {
  const port = process.env.PORT || 3000;
  app.listen(port, () => {
    console.log(`Server running on port ${port}`);
  });
}

module.exports = app;

