  "license": "ISC"
}

const assert = require('assert');
const app = require('./app');

const server = app.listen(0, async () => {
  try {
    const port = server.address().port;

    const healthResponse = await fetch(`http://127.0.0.1:${port}/health`);
    assert.strictEqual(healthResponse.status, 200);
    const health = await healthResponse.json();
    assert.strictEqual(health.status, 'ok');
    assert.ok(/^[0-9]{4}-[0-9]{2}-[0-9]{2}T/.test(health.timestamp));

    const usersResponse = await fetch(`http://127.0.0.1:${port}/users`);
    assert.strictEqual(usersResponse.status, 200);
    assert.deepStrictEqual(await usersResponse.json(), [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);

    const missingResponse = await fetch(`http://127.0.0.1:${port}/missing`);
    assert.strictEqual(missingResponse.status, 404);

    console.log('All tests passed');
  } catch (error) {
    console.error(error);
    process.exitCode = 1;
  } finally {
    server.close();
  }
});
